<?php use NxMultiTool\Registry; use NxMultiTool\AdminController; ?>
<section class="nxmt-panel"><p>公開側の受付は現在 <strong><?= $settings['comments_open'] ? '有効' : '停止中' ?></strong> です。ダッシュボードの共通設定で変更できます。投稿はすべて承認待ちになり、本文はプレーンテキストで表示されます。</p><form method="get" action="<?= e(Registry::url()) ?>"><input type="hidden" name="tool" value="comment_manager"><div class="nxmt-fields"><label>状態<select name="status"><?php foreach (['' => 'すべて', 'pending' => '承認待ち', 'approved' => '承認済み', 'spam' => 'スパム', 'trash' => 'ゴミ箱'] as $key => $label): ?><option value="<?= e($key) ?>" <?= ($_GET['status'] ?? '') === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>名前・本文・IPを検索<input name="q" value="<?= e(is_string($_GET['q'] ?? null) ? $_GET['q'] : '') ?>"></label><label>記事ID<input name="content_id" type="number" min="1" value="<?= e(is_scalar($_GET['content_id'] ?? null) ? (string)$_GET['content_id'] : '') ?>"></label></div><button type="submit">絞り込む</button></form></section>
<?php if ($data['review']): ?><section class="nxmt-panel nxmt-review"><h2>スパム指定とIP拒否の対象確認</h2><p>次のコメントをスパムにし、送信元IPを<?= (int)$settings['block_hours'] ?>時間拒否します。共有回線の他の利用者にも影響する場合があります。</p><ul><?php foreach ($data['review']['rows'] as $row): ?><li>ID <?= (int)$row['id'] ?> · IP <?= e($row['ip']) ?></li><?php endforeach; ?></ul><form method="post" action="<?= e(Registry::endpoint('action')) ?>"><?php AdminController::form('comment_manager', 'confirm_block'); ?><input type="hidden" name="review_token" value="<?= e($data['review']['token']) ?>"><button>この対象へ実行</button><button name="op" value="cancel_block" class="secondary">キャンセル</button></form></section><?php endif; ?>
<form id="nxmt-comment-bulk" method="post" action="<?= e(Registry::endpoint('action')) ?>" class="nxmt-inline"><?php AdminController::form('comment_manager', ''); ?><label>選択したコメントを<select name="op"><option value="approved">承認済みにする</option><option value="pending">承認待ちにする</option><option value="spam">スパムにする（IP拒否なし）</option><option value="prepare_block">スパム＋IP拒否の対象を確認</option><option value="trash">ゴミ箱へ移動</option><option value="delete">ゴミ箱から完全削除</option></select></label><button type="submit" data-confirm="選択したコメントへ操作しますか？">適用</button></form>
<div class="nxmt-table-wrap"><table><thead><tr><th>選択</th><th>記事</th><th>投稿者</th><th>IP</th><th>本文</th><th>状態</th><th>日時</th></tr></thead><tbody><?php foreach ($data['rows'] as $row): ?><tr><td><input form="nxmt-comment-bulk" type="checkbox" name="ids[]" value="<?= (int)$row['id'] ?>" aria-label="コメント<?= (int)$row['id'] ?>"></td><td><?= e($row['content_type']) ?> #<?= (int)$row['content_id'] ?></td><td><?= e($row['name']) ?><small><?= e($row['email']) ?></small></td><td><?= e($row['ip']) ?><small><?= \NxMultiTool\Monitor::blocked($row['ip']) ? '拒否中' : '未拒否' ?></small><a href="<?= e(Registry::url('access_log') . '&ip=' . rawurlencode($row['ip'])) ?>">同じIPのアクセス</a><form method="post" action="<?= e(Registry::endpoint('action')) ?>"><?php AdminController::form('comment_manager', 'unblock'); ?><input type="hidden" name="ip" value="<?= e($row['ip']) ?>"><button type="submit" class="secondary">拒否解除</button></form></td><td class="nxmt-comment-body"><?= nl2br(e($row['body'])) ?></td><td><?= e($row['status']) ?></td><td><?= e(date('Y-m-d H:i:s', $row['created_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php AdminController::pagination('comment_manager', $page, $data['total']); ?>
